  void Init(const Byte* b, size_t s) {
    buf=b; size=s; pos=0; range=0xFFFFFFFF; code=0; error=false;
    for (int i=0;i<5;i++) {
      if (pos>=size) { error=true; return; }
      code = (code<<8) | buf[pos++];
    }
    if (buf[0] != 0) error = true;
  }
  Byte ReadByte() { if (pos>=size){error=true;return 0;} return buf[pos++]; }
  void Normalize() { if (range < kTopValue) { range <<= 8; code = (code<<8)|ReadByte(); } }
  uint32_t DecodeBit(uint16_t& prob) {
    uint32_t bound = (range >> 11) * prob;
    uint32_t bit;
    if (code < bound) { range = bound; prob = (uint16_t)(prob + ((kBitModelTotal - prob) >> 5)); bit = 0; }
    else { range -= bound; code -= bound; prob = (uint16_t)(prob - (prob >> 5)); bit = 1; }
    Normalize();
    return bit;
  }
  uint32_t DecodeDirectBits(int n) {
    uint32_t v = 0;
    while (n-- > 0) {
      range >>= 1;
      v <<= 1;
      if (code >= range) { code -= range; v |= 1; }
      Normalize();
    }
    return v;
  }
};
