Bit tree decode:
```cpp
static uint32_t BitTreeDecode(RangeDec& rc, uint16_t* probs, int numBits) {
  uint32_t m = 1;
  for (int i=0;i<numBits;i++) m = (m<<1) | rc.DecodeBit(probs[m]);
  return m - (1u<<numBits);
}
static uint32_t BitTreeReverseDecode(RangeDec& rc, uint16_t* probs, int numBits) {
  uint32_t m=1, v=0;
  for (int i=0;i<numBits;i++){ uint32_t b = rc.DecodeBit(probs[m]); m=(m<<1)|b; v |= b<<i; }
  return v;
}
