bool Lzma2Decode(const Byte* in, size_t inSize, Byte* out, uint64_t outSize, Byte dictProp) {
  (void)dictProp;
  size_t pos = 0;
  uint64_t outPos = 0;
  LzmaDecoder dec;
  bool dictStarted = false; // first chunk must have dict reset
  while (pos < inSize) {
    Byte ctrl = in[pos++];
    if (ctrl == 0) break;
    uint32_t size;
    if (ctrl >= 0x80) {
      if (pos + 4 > inSize) return false;
      uint32_t unpack = (((uint32_t)ctrl & 0x1F) << 16) + ((uint32_t)in[pos] << 8) + in[pos+1] + 1;
      uint32_t pack = ((uint32_t)in[pos+2] << 8) + in[pos+3] + 1;
      pos += 4;
      int reset = (ctrl >> 5) & 3;
      if (reset >= 2) {
        if (pos >= inSize) return false;
        Byte pb = in[pos++];
        int lc = pb % 9; int rest = pb / 9; int lp = rest % 5; int pbb = rest / 5;
        if (lc > 4 || lp > 4 || pbb > 4) return false;
        dec.SetProps(lc, lp, pbb);
      }
      if (reset >= 1) dec.ResetState();
      if (reset == 3) { dec.ResetDictAt(outPos); dictStarted = true; }
      // note: need props set before ResetState? ResetState inits probs incl. lit array which depends on props. Order: SetProps allocates lit array; ResetState fills. If reset==1 without props... props must have been set by an earlier chunk. First compressed chunk must have reset>=2. Track hasProps.
      if (outPos + unpack > outSize) return false;
      if (pos + pack > inSize) return false;
      size_t consumed; uint64_t produced;
      if (!dec.Run(in+pos, pack, out, outPos, unpack, false, &consumed, &produced)) return false;
      if (consumed != pack || produced != unpack) return false;
      pos += pack; outPos += unpack;
    } else if (ctrl <= 2) {
      if (pos + 2 > inSize) return false;
      size = ((uint32_t)in[pos] << 8) + in[pos+1] + 1;
      pos += 2;
      if (ctrl == 1) { dec.ResetDictAt(outPos); dictStarted = true; }
      if (pos + size > inSize || outPos + size > outSize) return false;
      memcpy(out + outPos, in + pos, size);
      pos += size; outPos += size;
    } else return false;
  }
  return outPos == outSize;
}
