bool LzmaProps::ParseProps(const Byte* p, size_t size) {
  if (size < 5) return false;
  Byte b = p[0];
  if (b > 224) return false; // (4*5+4)*9+8
  lc = b % 9; int r = b/9; lp = r % 5; pb = r / 5;
  dictSize = Get32(p+1);
  return true;
}
