// LZMA / LZMA2 decoder — original implementation from the LZMA format
// specification (range coder + adaptive binary probability models).
#include "Lzma.h"
#include <algorithm>

namespace {

constexpr uint32_t kTopValue       = 1u << 24;   // range coder renormalization threshold
constexpr int      kNumMoveBits    = 5;          // probability adaption shift
constexpr uint16_t kProbInit       = 1u << 10;   // 0.5 in 11-bit fixed point
constexpr int      kNumStates      = 12;
constexpr int      kNumPosBitsMax  = 4;
constexpr int      kMatchMinLen    = 2;
constexpr int      kEndPosModelOff = 14;
constexpr int      kNumAlignBits   = 4;
constexpr int      kNumLitContext  = 0x300;      // probs per literal context

// ---------------------------------------------------------------- range coder

class RangeDec {
public:
  const Byte* buf = nullptr;
  size_t size = 0, pos = 0;
  uint32_t range = 0, code = 0;
  bool error = false;

  void Init(const Byte* b, size_t s) {
    buf = b; size = s; pos = 0;
    range = 0xFFFFFFFFu; code = 0; error = false;
    if (s < 5 || b[0] != 0) { error = true; return; }
    pos = 1;
    for (int i = 0; i < 4; i++)
      code = (code << 8) | buf[pos++];
  }

  void Normalize() {
    if (range < kTopValue) {
      if (pos >= size) { error = true; return; }
      range <<= 8;
      code = (code << 8) | buf[pos++];
    }
  }

  uint32_t DecodeBit(uint16_t& prob) {
    uint32_t bound = (range >> 11) * prob;
    uint32_t bit;
    if (code < bound) {
      range = bound;
      prob = (uint16_t)(prob + ((0x800u - prob) >> kNumMoveBits));
      bit = 0;
    } else {
      range -= bound;
      code -= bound;
      prob = (uint16_t)(prob - (prob >> kNumMoveBits));
      bit = 1;
    }
    Normalize();
    return bit;
  }

  uint32_t DecodeDirectBits(int n) {
    uint32_t v = 0;
    while (n-- > 0) {
      range >>= 1;
      v <<= 1;
      if (code >= range) { code -= range; v |= 1; }
      Normalize();
    }
    return v;
  }
};

static uint32_t BitTreeDecode(RangeDec& rc, uint16_t* probs, int numBits) {
  uint32_t m = 1;
  for (int i = 0; i < numBits; i++)
    m = (m << 1) | rc.DecodeBit(probs[m]);
  return m - (1u << numBits);
}

static uint32_t BitTreeReverseDecode(RangeDec& rc, uint16_t* probs, int numBits) {
  uint32_t m = 1, v = 0;
  for (int i = 0; i < numBits; i++) {
    uint32_t b = rc.DecodeBit(probs[m]);
    m = (m << 1) | b;
    v |= b << i;
  }
  return v;
}

// ------------------------------------------------------------- length coder

struct LenCoder {
  uint16_t choice, choice2;
  uint16_t low[1 << kNumPosBitsMax][8];
  uint16_t mid[1 << kNumPosBitsMax][8];
  uint16_t high[256];

  void Init() {
    choice = choice2 = kProbInit;
    std::fill(&low[0][0], &low[0][0] + (1 << kNumPosBitsMax) * 8, kProbInit);
    std::fill(&mid[0][0], &mid[0][0] + (1 << kNumPosBitsMax) * 8, kProbInit);
    std::fill(high, high + 256, kProbInit);
  }

  // returns 0..(273-kMatchMinLen)
  uint32_t Decode(RangeDec& rc, uint32_t posState) {
    if (!rc.DecodeBit(choice))
      return BitTreeDecode(rc, low[posState], 3);
    if (!rc.DecodeBit(choice2))
      return 8 + BitTreeDecode(rc, mid[posState], 3);
    return 16 + BitTreeDecode(rc, high, 8);
  }
};

// ------------------------------------------------------------------ decoder

// Probability state + repetition history. The output window is the caller's
// buffer; positions for contexts (lp/pb) and distance checks are taken
// relative to winStart_, which moves only on a dictionary reset (LZMA2).
class LzmaDecoder {
public:
  bool SetProps(int lc, int lp, int pb) {
    if (lc < 0 || lc > 8 || lp < 0 || lp > 4 || pb < 0 || pb > 4)
      return false;
    lc_ = lc; lp_ = lp;
    lpMask_ = (1u << lp) - 1;
    pbMask_ = (1u << pb) - 1;
    lit_.assign(size_t(kNumLitContext) << (lc + lp), kProbInit);
    hasProps_ = true;
    return true;
  }

  // Reset probabilities, state machine and rep distances. The output window
  // (and virtual position) is untouched, so LZMA2 chunks can continue.
  void ResetState() {
    state_ = 0;
    rep0_ = rep1_ = rep2_ = rep3_ = 1;
    std::fill(&isMatch_[0][0], &isMatch_[0][0] + kNumStates * (1 << kNumPosBitsMax), kProbInit);
    std::fill(isRep_, isRep_ + kNumStates, kProbInit);
    std::fill(isRepG0_, isRepG0_ + kNumStates, kProbInit);
    std::fill(isRepG1_, isRepG1_ + kNumStates, kProbInit);
    std::fill(isRepG2_, isRepG2_ + kNumStates, kProbInit);
    std::fill(&isRep0Long_[0][0], &isRep0Long_[0][0] + kNumStates * (1 << kNumPosBitsMax), kProbInit);
    std::fill(&posSlot_[0][0], &posSlot_[0][0] + 4 * 64, kProbInit);
    std::fill(specPos_, specPos_ + 128, kProbInit);
    std::fill(posAlign_, posAlign_ + 16, kProbInit);
    lenCoder_.Init();
    repLenCoder_.Init();
    if (hasProps_)
      std::fill(lit_.begin(), lit_.end(), kProbInit);
  }

  void SetWindow(Byte* out, uint64_t outPos, uint64_t winStart) {
    out_ = out; outPos_ = outPos; winStart_ = winStart;
  }

  // Decode raw LZMA symbols until either outCount bytes have been produced
  // or (only when allowMarker) an end-of-stream marker is reached.
  // Returns false on data error. *consumed / *produced are always set.
  bool Run(const Byte* in, size_t inSize, uint64_t outCount, bool allowMarker,
           size_t* consumed, uint64_t* produced) {
    if (!hasProps_) return false;
    RangeDec rc;
    rc.Init(in, inSize);
    uint64_t limit = outPos_ + outCount; // may wrap to -1: intended for unknown size
    if (outCount == UINT64_MAX) limit = UINT64_MAX;
    bool sawMarker = false;
    while (outPos_ < limit) {
      if (rc.error) return false;
      uint64_t rel = outPos_ - winStart_;
      uint32_t posState = (uint32_t)(rel & pbMask_);

      if (!rc.DecodeBit(isMatch_[state_][posState])) {
        // ---- literal
        Byte prev = rel ? out_[outPos_ - 1] : (Byte)0;
        uint32_t ctx = ((uint32_t)(rel & lpMask_) << lc_) +
                       (lc_ ? (uint32_t)(prev >> (8 - lc_)) : 0u);
        uint16_t* probs = &lit_[size_t(kNumLitContext) * ctx];
        uint32_t sym = 1;
        if (state_ >= 7) {
          // matched-literal mode: use the byte at the current rep0 distance
          Byte matchByte = out_[outPos_ - rep0_ - 1];
          do {
            uint32_t matchBit = (matchByte >> 7) & 1;
            matchByte = (Byte)(matchByte << 1);
            uint32_t bit = rc.DecodeBit(probs[((1 + matchBit) << 8) + sym]);
            sym = (sym << 1) | bit;
            if (matchBit != bit) break;
          } while (sym < 0x100);
        }
        while (sym < 0x100)
          sym = (sym << 1) | rc.DecodeBit(probs[sym]);
        out_[outPos_++] = (Byte)sym;
        state_ = (state_ < 4) ? 0 : (state_ < 10 ? state_ - 3 : state_ - 6);
        continue;
      }

      uint32_t len;
      if (rc.DecodeBit(isRep_[state_])) {
        // ---- repeated match
        if (!rc.DecodeBit(isRepG0_[state_])) {
          if (!rc.DecodeBit(isRep0Long_[state_][posState])) {
            // short rep: single byte at distance rep0+1
            state_ = state_ < 7 ? 9 : 11;
            if ((uint64_t)rep0_ + 1 > rel) return false;
            out_[outPos_] = out_[outPos_ - rep0_ - 1];
            outPos_++;
            continue;
          }
        } else {
          uint32_t dist;
          if (!rc.DecodeBit(isRepG1_[state_])) {
            dist = rep1_;
          } else {
            if (!rc.DecodeBit(isRepG2_[state_])) {
              dist = rep2_;
            } else {
              dist = rep3_;
              rep3_ = rep2_;
            }
            rep2_ = rep1_;
          }
          rep1_ = rep0_;
          rep0_ = dist;
        }
        len = repLenCoder_.Decode(rc, posState);
        state_ = state_ < 7 ? 8 : 11;
      } else {
        // ---- simple match: decode new distance
        rep3_ = rep2_; rep2_ = rep1_; rep1_ = rep0_;
        len = lenCoder_.Decode(rc, posState);
        state_ = state_ < 7 ? 7 : 10;
        uint32_t lenToPosState = len < 3 ? len : 3;
        uint32_t slot = BitTreeDecode(rc, posSlot_[lenToPosState], 6);
        if (slot < 4) {
          rep0_ = slot;
        } else {
          int numDirect = (int)(slot >> 1) - 1;
          rep0_ = (2u | (slot & 1)) << numDirect;
          if (slot < kEndPosModelOff) {
            // low distance bits via SpecPos, indexed from (base - slot - 1)
            int off = (int)rep0_ - (int)slot - 1;
            uint32_t m = 1, v = 0;
            for (int i = 0; i < numDirect; i++) {
              uint32_t b = rc.DecodeBit(specPos_[off + (int)m]);
              m = (m << 1) | b;
              v |= b << i;
            }
            rep0_ += v;
          } else {
            rep0_ += rc.DecodeDirectBits(numDirect - kNumAlignBits) << kNumAlignBits;
            rep0_ += BitTreeReverseDecode(rc, posAlign_, kNumAlignBits);
          }
        }
        if (rep0_ == 0xFFFFFFFFu) {
          // end-of-stream marker
          if (!allowMarker) return false;
          sawMarker = true;
          break;
        }
      }

      len += kMatchMinLen;
      if (rc.error) return false;
      if ((uint64_t)rep0_ + 1 > rel) return false;   // distance crosses dict start
      if (len > limit - outPos_) return false;       // would overflow known size
      Byte* dst = out_ + outPos_;
      const Byte* src = dst - rep0_ - 1;
      for (uint32_t i = 0; i < len; i++)
        dst[i] = src[i];
      outPos_ += len;
    }
    if (rc.error) return false;
    if (allowMarker && !sawMarker && outPos_ < limit) return false;
    if (consumed) *consumed = rc.pos;
    if (produced) *produced = outPos_;
    return true;
  }

private:
  int lc_ = 0, lp_ = 0;
  uint32_t lpMask_ = 0, pbMask_ = 0;
  bool hasProps_ = false;

  Byte* out_ = nullptr;
  uint64_t outPos_ = 0, winStart_ = 0;

  uint32_t state_ = 0;
  uint32_t rep0_ = 1, rep1_ = 1, rep2_ = 1, rep3_ = 1;

  uint16_t isMatch_[kNumStates][1 << kNumPosBitsMax];
  uint16_t isRep_[kNumStates];
  uint16_t isRepG0_[kNumStates];
  uint16_t isRepG1_[kNumStates];
  uint16_t isRepG2_[kNumStates];
  uint16_t isRep0Long_[kNumStates][1 << kNumPosBitsMax];
  uint16_t posSlot_[4][64];
  uint16_t specPos_[128];  // kNumFullDistances - kEndPosModelOff + padding
  uint16_t posAlign_[16];
  LenCoder lenCoder_, repLenCoder_;
  std::vector<uint16_t> lit_;
};

} // namespace

// ------------------------------------------------------------------ public

bool LzmaProps::ParseProps(const Byte* p, size_t size) {
  if (size < 5) return false;
  Byte b = p[0];
  if (b > (Byte)((4 * 5 + 4) * 9 + 8)) return false; // lc<=8, lp<=4, pb<=4
  lc = b % 9;
  int r = b / 9;
  lp = r % 5;
  pb = r / 5;
  dictSize = Get32(p + 1);
  return true;
}

bool LzmaDecode(const Byte* in, size_t inSize, Byte* out, uint64_t outSize,
                const LzmaProps& props, size_t* inConsumed) {
  if (props.lc > 8 || props.lp > 4 || props.pb > 4 ||
      props.lc < 0 || props.lp < 0 || props.pb < 0)
    return false;
  LzmaDecoder dec;
  if (!dec.SetProps(props.lc, props.lp, props.pb)) return false;
  dec.ResetState();
  dec.SetWindow(out, 0, 0);
  bool marker = (outSize == UINT64_MAX);
  size_t consumed = 0;
  uint64_t produced = 0;
  if (!dec.Run(in, inSize, marker ? UINT64_MAX : outSize, marker,
               &consumed, &produced))
    return false;
  if (!marker && produced != outSize) return false;
  if (inConsumed) *inConsumed = consumed;
  return true;
}

bool Lzma2Decode(const Byte* in, size_t inSize, Byte* out, uint64_t outSize, Byte dictProp) {
  (void)dictProp; // dict size is irrelevant: matches never cross a dict reset
  LzmaDecoder dec;
  dec.SetWindow(out, 0, 0);
  size_t pos = 0;
  uint64_t outPos = 0, winStart = 0;
  bool dictStarted = false;
  bool hasProps = false;

  while (pos < inSize) {
    Byte ctrl = in[pos++];
    if (ctrl == 0)
      break; // end of LZMA2 stream
    if (ctrl >= 0x80) {
      // ---- compressed chunk
      if (pos + 4 > inSize) return false;
      uint32_t unpack = (((uint32_t)ctrl & 0x1F) << 16) +
                        ((uint32_t)in[pos] << 8) + in[pos + 1] + 1;
      uint32_t pack = ((uint32_t)in[pos + 2] << 8) + in[pos + 3] + 1;
      pos += 4;
      int reset = (ctrl >> 5) & 3;
      if (reset >= 2) {
        // new properties byte follows
        if (pos >= inSize) return false;
        Byte b = in[pos++];
        if (b > (Byte)((4 * 5 + 4) * 9 + 4)) return false; // lc<=4 in LZMA2
        int lc = b % 9, r = b / 9, lp = r % 5, pb = r / 5;
        if (!dec.SetProps(lc, lp, pb)) return false;
        hasProps = true;
      }
      if (!hasProps) return false;
      if (reset >= 1)
        dec.ResetState();
      if (reset == 3) {
        winStart = outPos; // dictionary reset
        dictStarted = true;
      }
      if (!dictStarted) return false; // first chunk must reset the dictionary
      if (outSize - outPos < unpack) return false;
      if (inSize - pos < pack) return false;
      dec.SetWindow(out, outPos, winStart);
      size_t consumed = 0;
      uint64_t produced = 0;
      if (!dec.Run(in + pos, pack, unpack, false, &consumed, &produced))
        return false;
      if (produced != outPos + unpack) return false;
      pos += pack; // trust the chunk header for the packed size
      outPos += unpack;
    } else if (ctrl <= 2) {
      // ---- uncompressed chunk (1 = dict reset, 2 = no reset)
      if (pos + 2 > inSize) return false;
      uint32_t size = ((uint32_t)in[pos] << 8) + in[pos + 1] + 1;
      pos += 2;
      if (ctrl == 1) {
        winStart = outPos;
        dictStarted = true;
      }
      if (!dictStarted) return false;
      if (outSize - outPos < size) return false;
      if (inSize - pos < size) return false;
      memcpy(out + outPos, in + pos, size);
      pos += size;
      outPos += size;
    } else {
      return false; // 0x03..0x7F are reserved
    }
  }
  return outPos == outSize;
}

// Test harness for src/LzmaDec.cpp — parses xz and 7z containers just far
// enough to extract LZMA/LZMA2 streams, decodes, and compares to known data.
#include "../src/Lzma.h"
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>
#include <map>

static ByteBuf ReadFile(const std::string& p) {
  FILE* f = fopen(p.c_str(), "rb");
  if (!f) { fprintf(stderr, "cannot open %s\n", p.c_str()); exit(1); }
  fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
  ByteBuf b(n); if (n) { if (fread(b.data(), 1, n, f) != (size_t)n) exit(1); }
  fclose(f); return b;
}

static int failures = 0;
#define CHECK(cond, msg) do { if (!(cond)) { printf("FAIL: %s\n", msg); failures++; } } while (0)

// ---------------- varint (7z/xz style) ----------------
static uint64_t GetVar(const Byte* p, size_t size, size_t& pos) {
  uint64_t v = 0; int shift = 0;
  while (pos < size) {
    Byte b = p[pos++];
    v |= (uint64_t)(b & 0x7F) << shift;
    if (!(b & 0x80)) break;
    shift += 7;
  }
  return v;
}

// ---------------- xz parsing ----------------
struct XzBlock {
  Byte dictProp;
  const Byte* lzma2;
  size_t lzma2Size;   // upper bound (to end of file minus index); exact end found by decoder loop
  uint64_t unpackSize; // from block header if present, else 0 (unknown)
};

static bool ParseXz(const ByteBuf& f, XzBlock& blk) {
  if (f.size() < 12) return false;
  static const Byte magic[6] = {0xFD, '7', 'z', 'X', 'Z', 0};
  if (memcmp(f.data(), magic, 6) != 0) return false;
  size_t pos = 12; // skip magic + stream flags + CRC32
  if (pos >= f.size()) return false;
  size_t hdrStart = pos;
  size_t hdrSize = (size_t)(f[pos] + 1) * 4;
  if (hdrStart + hdrSize > f.size()) return false;
  Byte flags = f[pos + 1];
  int numFilters = (flags & 3) + 1;
  pos += 2;
  uint64_t compSize = 0, uncompSize = 0;
  if (flags & 0x40) compSize = GetVar(f.data(), hdrStart + hdrSize, pos);
  if (flags & 0x80) uncompSize = GetVar(f.data(), hdrStart + hdrSize, pos);
  if (numFilters != 1) return false;
  uint64_t id = GetVar(f.data(), hdrStart + hdrSize, pos);
  if (id != 0x21) { printf("xz filter id 0x%llx not LZMA2\n", (unsigned long long)id); return false; }
  uint64_t propSize = GetVar(f.data(), hdrStart + hdrSize, pos);
  if (propSize != 1) return false;
  blk.dictProp = f[pos];
  blk.lzma2 = f.data() + hdrStart + hdrSize;
  blk.lzma2Size = f.size() - (hdrStart + hdrSize);
  blk.unpackSize = uncompSize;
  (void)compSize;
  return true;
}

// ---------------- 7z parsing (minimal) ----------------
struct SevenZFolder {
  Byte codecId;          // 0x21 LZMA2, 0x03 LZMA (first id byte)
  ByteBuf props;
  uint64_t unpackSize;   // sum of out-stream sizes (single coder assumed)
  uint64_t packSize;
  uint64_t packPos;      // relative to offset 32
  uint64_t numSubStreams;
  std::vector<uint64_t> subSizes; // per-substream unpack sizes (if known)
  std::vector<std::string> names;
};

struct Reader {
  const Byte* p; size_t size, pos;
  uint64_t var() { uint64_t v = 0; int s = 0; while (pos < size) { Byte b = p[pos++]; v |= (uint64_t)(b & 0x7F) << s; if (!(b & 0x80)) break; s += 7; } return v; }
  Byte u8() { return pos < size ? p[pos++] : 0; }
  uint64_t u32() { uint64_t v = Get32(p + pos); pos += 4; return v; }
  uint64_t u64() { uint64_t v = Get64(p + pos); pos += 8; return v; }
  bool allDefined(uint64_t n, bool& defined) {
    Byte b = u8();
    if (b == 0) { defined = false; return true; }
    defined = (b != 0); // 0 means "all defined" actually; handle: byte!=0 -> bitmask follows
    // 7z: first byte 0 => all defined; 1 => not all defined, then bitmask
    // (spec: 0x00 = all defined)
    return true;
  }
};

static bool SkipCrcVector(Reader& r, uint64_t count) {
  Byte all = r.u8();
  if (all == 0) { // all defined
    r.pos += 4 * count;
  } else {
    uint64_t bytes = (count + 7) / 8;
    uint64_t set = 0;
    std::vector<Byte> mask(bytes);
    for (uint64_t i = 0; i < bytes; i++) mask[i] = r.u8();
    for (uint64_t i = 0; i < count; i++)
      if (mask[i / 8] & (1 << (i % 8))) set++;
    r.pos += 4 * set;
  }
  return r.pos <= r.size;
}

static bool ParseStreamsInfo(Reader& r, std::vector<SevenZFolder>& folders) {
  Byte id = r.u8();
  if (id != 0x06) return false; // kPackInfo
  uint64_t packPos = r.var();
  uint64_t numPack = r.var();
  std::vector<uint64_t> packSizes;
  for (;;) {
    id = r.u8();
    if (id == 0) break;
    uint64_t sz = r.var(); (void)sz;
    if (id == 0x09) { // kSize
      for (uint64_t i = 0; i < numPack; i++) packSizes.push_back(r.var());
    } else if (id == 0x0A) { // kCRC
      SkipCrcVector(r, numPack);
    } else {
      r.pos += sz;
    }
  }
  id = r.u8();
  if (id != 0x07) return false; // kUnpackInfo
  if (r.u8() != 0x0B) return false; // kFolder
  uint64_t numFolders = r.var();
  if (r.u8() != 0) return false; // external
  folders.resize(numFolders);
  for (uint64_t fi = 0; fi < numFolders; fi++) {
    SevenZFolder& fo = folders[fi];
    fo.packPos = packPos;
    uint64_t numCoders = r.var();
    if (numCoders != 1) return false; // harness only supports plain LZMA/LZMA2
    Byte fl = r.u8();
    int idSize = fl & 0xF;
    if (fl & 0xF0) return false; // no attrs/alt streams expected
    std::vector<Byte> cid(idSize);
    for (int i = 0; i < idSize; i++) cid[i] = r.u8();
    fo.codecId = cid[0];
  }
  // end of folder list
  if (r.u8() != 0) return false;
  if (r.u8() != 0x0C) return false; // kCodersUnpackSize
  for (uint64_t fi = 0; fi < numFolders; fi++)
    folders[fi].unpackSize = r.var();
  for (;;) {
    id = r.u8();
    if (id == 0) break;
    uint64_t sz = r.var(); (void)sz;
    if (id == 0x0A) SkipCrcVector(r, numFolders);
    else r.pos += sz;
  }
  // SubStreamsInfo (optional)
  if (r.pos < r.size && r.p[r.pos] == 0x08) {
    r.pos++;
    for (;;) {
      id = r.u8();
      if (id == 0) break;
      uint64_t sz = r.var(); (void)sz;
      if (id == 0x0D) { // kNumUnpackStream
        for (uint64_t fi = 0; fi < numFolders; fi++)
          folders[fi].numSubStreams = r.var();
      } else if (id == 0x09) { // kSize: per folder, numSubStreams-1 sizes
        for (uint64_t fi = 0; fi < numFolders; fi++) {
          uint64_t ns = folders[fi].numSubStreams ? folders[fi].numSubStreams : 1;
          uint64_t sum = 0;
          for (uint64_t i = 0; i + 1 < ns; i++) {
            uint64_t v = r.var();
            folders[fi].subSizes.push_back(v);
            sum += v;
          }
          if (ns > 0) folders[fi].subSizes.push_back(folders[fi].unpackSize - sum);
        }
      } else if (id == 0x0A) {
        uint64_t total = 0;
        for (auto& fo : folders) total += fo.numSubStreams ? fo.numSubStreams : 1;
        SkipCrcVector(r, total);
      } else r.pos += sz;
    }
  }
  // pack sizes: single pack stream per folder assumed in order
  for (uint64_t fi = 0; fi < numFolders && fi < packSizes.size(); fi++)
    folders[fi].packSize = packSizes[fi];
  return true;
}

static bool Parse7zHeader(const Byte* h, size_t hsize, std::vector<SevenZFolder>& folders) {
  Reader r{h, hsize, 0};
  Byte id = r.u8();
  if (id != 0x01) return false; // kHeader
  if (r.u8() != 0x04) return false; // kMainStreamsInfo
  // StreamsInfo ends where FilesInfo begins; parse then continue
  size_t before = r.pos;
  (void)before;
  if (!ParseStreamsInfo(r, folders)) return false;
  if (r.u8() != 0) return false; // end of main streams info
  if (r.u8() != 0x05) return false; // kFilesInfo
  uint64_t numFiles = r.var();
  // read properties; collect names
  uint64_t emptyStreams = 0;
  std::vector<Byte> emptyMask, antiMask;
  for (;;) {
    id = r.u8();
    if (id == 0) break;
    uint64_t sz = r.var();
    size_t end = r.pos + sz;
    if (id == 0x11) { // kName
      if (r.u8() != 0) return false;
      for (uint64_t i = 0; i < numFiles; i++) {
        std::string n;
        while (r.pos + 1 < end) {
          uint16_t c = r.p[r.pos] | (r.p[r.pos + 1] << 8);
          r.pos += 2;
          if (!c) break;
          n += (char)c;
        }
        folders[0].names.push_back(n); // single folder harness
      }
    } else if (id == 0x0E) { // kEmptyStream
      emptyStreams = 0;
      for (uint64_t i = 0; i < numFiles; i++) {
        Byte b = r.p[r.pos + i / 8];
        if (b & (1 << (i % 8))) emptyStreams++;
      }
      emptyMask.assign(r.p + r.pos, r.p + r.pos + (numFiles + 7) / 8);
    } else if (id == 0x0F) { // kAnti
      antiMask.assign(r.p + r.pos, r.p + r.pos + (emptyStreams + 7) / 8);
    }
    r.pos = end;
  }
  return true;
}

static bool Parse7z(const ByteBuf& f, std::vector<SevenZFolder>& folders,
                    const Byte** encodedHdrStream, uint64_t* encHdrSize) {
  static const Byte sig[6] = {'7', 'z', 0xBC, 0xAF, 0x27, 0x1C};
  if (f.size() < 32 || memcmp(f.data(), sig, 6) != 0) return false;
  uint64_t nhOff = Get64(f.data() + 12);
  uint64_t nhSize = Get64(f.data() + 20);
  if (32 + nhOff + nhSize > f.size()) return false;
  const Byte* h = f.data() + 32 + nhOff;
  if (nhSize == 0) return false;
  if (h[0] == 0x01) {
    *encodedHdrStream = nullptr;
    return Parse7zHeader(h, nhSize, folders);
  }
  if (h[0] == 0x17) { // kEncodedHeader
    Reader r{h + 1, nhSize - 1, 0};
    std::vector<SevenZFolder> hf;
    if (!ParseStreamsInfo(r, hf)) return false;
    if (r.u8() != 0) return false;
    *encodedHdrStream = f.data() + 32 + hf[0].packPos;
    *encHdrSize = hf[0].unpackSize;
    // decode the header now
    ByteBuf dec(hf[0].unpackSize);
    const SevenZFolder& fo = hf[0];
    bool ok;
    if (fo.codecId == 0x21)
      ok = Lzma2Decode(*encodedHdrStream, fo.packSize, dec.data(), fo.unpackSize, fo.props[0]);
    else {
      LzmaProps pr;
      if (!pr.ParseProps(fo.props.data(), fo.props.size())) return false;
      ok = LzmaDecode(*encodedHdrStream, fo.packSize, dec.data(), fo.unpackSize, pr);
    }
    if (!ok) { printf("FAIL: encoded header decode\n"); return false; }
    return Parse7zHeader(dec.data(), dec.size(), folders);
  }
  return false;
}

// ---------------- tests ----------------

static void TestXz(const std::string& xzPath, const std::string& rawPath) {
  ByteBuf xz = ReadFile(xzPath);
  ByteBuf raw = ReadFile(rawPath);
  XzBlock blk;
  if (!ParseXz(xz, blk)) { printf("FAIL: parse xz %s\n", xzPath.c_str()); failures++; return; }
  ByteBuf out(raw.size() ? raw.size() : 1);
  bool ok = Lzma2Decode(blk.lzma2, blk.lzma2Size, out.data(), raw.size(), blk.dictProp);
  CHECK(ok, xzPath.c_str());
  CHECK(ok && memcmp(out.data(), raw.data(), raw.size()) == 0, "xz content mismatch");
  printf("xz test %-30s dictProp=%u raw=%zu : %s\n", xzPath.c_str(), blk.dictProp,
         raw.size(), (ok && memcmp(out.data(), raw.data(), raw.size()) == 0) ? "OK" : "FAIL");
}

static void Test7z(const std::string& path, const std::map<std::string, ByteBuf>& expected) {
  ByteBuf a = ReadFile(path);
  std::vector<SevenZFolder> folders;
  const Byte* enc; uint64_t encSize;
  if (!Parse7z(a, folders, &enc, &encSize)) { printf("FAIL: parse 7z %s\n", path.c_str()); failures++; return; }
  for (auto& fo : folders) {
    const Byte* pack = a.data() + 32 + fo.packPos;
    ByteBuf dec(fo.unpackSize ? fo.unpackSize : 1);
    bool ok;
    if (fo.codecId == 0x21) {
      ok = Lzma2Decode(pack, fo.packSize, dec.data(), fo.unpackSize, fo.props[0]);
    } else if (fo.codecId == 0x03) {
      LzmaProps pr;
      ok = pr.ParseProps(fo.props.data(), fo.props.size()) &&
           LzmaDecode(pack, fo.packSize, dec.data(), fo.unpackSize, pr);
    } else {
      printf("FAIL: %s codec 0x%02X unsupported in harness\n", path.c_str(), fo.codecId);
      failures++; continue;
    }
    CHECK(ok, path.c_str());
    if (!ok) continue;
    // compare substreams to expected file contents (in header name order)
    uint64_t off = 0;
    size_t n = fo.names.size();
    for (size_t i = 0; i < n; i++) {
      auto it = expected.find(fo.names[i]);
      uint64_t sz = i < fo.subSizes.size() ? fo.subSizes[i] : (fo.unpackSize - off);
      if (it == expected.end()) { off += sz; continue; }
      CHECK(it->second.size() == sz, "size mismatch");
      CHECK(memcmp(dec.data() + off, it->second.data(), sz) == 0, "7z content mismatch");
      off += sz;
    }
    printf("7z test %-24s codec=0x%02X unpack=%llu files=%zu : OK\n", path.c_str(),
           fo.codecId, (unsigned long long)fo.unpackSize, n);
  }
}

int main(int argc, char** argv) {
  std::string w = "work/";
  TestXz(w + "hello.txt.xz", w + "hello.txt");
  if (argc > 1) return failures ? 1 : 0; // quick mode
  TestXz("/tmp/zeros.bin.xz", w + "zeros.bin");
  TestXz("/tmp/rand.bin.xz", w + "rand.bin");
  TestXz("/tmp/big.bin.xz", "/tmp/big.bin");

  std::map<std::string, ByteBuf> exp1;
  exp1["hello.txt"] = ReadFile(w + "hello.txt");
  Test7z("/tmp/lzma1.7z", exp1);   // forced LZMA1 codec

  std::map<std::string, ByteBuf> exp2;
  exp2["hello.txt"] = ReadFile(w + "hello.txt");
  exp2["a.txt"] = ReadFile(w + "a.txt");
  exp2["rand.bin"] = ReadFile(w + "rand.bin");
  exp2["zeros.bin"] = ReadFile(w + "zeros.bin");
  Test7z("/tmp/multi.7z", exp2);   // solid LZMA2, several files
  Test7z(w + "arc2.7z", {});       // just decode, no content check

  printf(failures ? "FAILURES: %d\n" : "ALL TESTS PASSED\n", failures);
  return failures ? 1 : 0;
}

