class RC:
    def __init__(s,b):
        s.b=b; s.pos=1; s.range=0xFFFFFFFF; s.code=int.from_bytes(b[1:5],'big')
    def norm(s):
        if s.range<TOP:
            s.range=(s.range<<8)&0xFFFFFFFF; s.code=((s.code<<8)|s.b[s.pos])&0xFFFFFFFF; s.pos+=1
    def bit(s,pr,i):
        bound=(s.range>>11)*pr[i]
        if s.code<bound: s.range=bound; pr[i]+= (0x800-pr[i])>>5; r=0
        else: s.range-=bound; s.code-=bound; pr[i]-=pr[i]>>5; r=1
        s.norm(); return r
    def direct(s,n):
        v=0
        for _ in range(n):
            s.range>>=1; v<<=1
            if s.code>=s.range: s.code-=s.range; v|=1
            s.norm()
        return v
def tree(rc,pr,off,n):
    m=1
    for _ in range(n): m=(m<<1)|rc.bit(pr,off+m)
    return m-(1<<n)
def rtree(rc,pr,off,n):
    m=1;v=0
    for i in range(n):
        b=rc.bit(pr,off+m); m=(m<<1)|b; v|=b<<i
    return v

def decode(data, outlen, lc=3,lp=0,pb=2, trace=False):
    P=[1024]*200000
    rc=RC(data)
    LIT=0; ISM=0x300*256; ISR=ISM+12*16; G0=ISR+12;G1=G0+12;G2=G1+12;I0L=G2+12
    SLOT=I0L+12*16; SPEC=SLOT+4*64; AL=SPEC+128
    LC=AL+16; RC_=LC+(2+16*8*2+256)
    def lendec(ps,base):
        if not rc.bit(P,base): return tree(rc,P,base+2+ps*8,3)
        if not rc.bit(P,base+1): return 8+tree(rc,P,base+2+128+ps*8,3)
        return 16+tree(rc,P,base+2+256,8)
    out=bytearray(); state=0; reps=[1,1,1,1]; sym=0
    while len(out)<outlen:
        ps=len(out)&3
        if not rc.bit(P,ISM+state*16+ps):
            prev=out[-1] if out else 0
            ctx=((len(out)&((1<<lp)-1))<<lc)+(prev>>(8-lc))
            base=LIT+0x300*ctx; sy=1
            if state>=7:
                mb=out[-reps[0]-1]
                while sy<0x100:
                    mbit=(mb>>7)&1; mb=(mb<<1)&0xFF
                    b=rc.bit(P,base+((1+mbit)<<8)+sy); sy=(sy<<1)|b
                    if mbit!=b: break
            while sy<0x100: sy=(sy<<1)|rc.bit(P,base+sy)
            out.append(sy&0xFF)
            state=0 if state<4 else (state-3 if state<10 else state-6)
            if trace: print(sym,"lit",hex(sy&0xFF),"pos",len(out)-1)
        else:
            if rc.bit(P,ISR+state):
                if not rc.bit(P,G0+state):
                    if not rc.bit(P,I0L+state*16+ps):
                        state=9 if state<7 else 11
                        if trace: print(sym,"shortrep pos",len(out))
                        out.append(out[-reps[0]-1]); sym+=1; continue
                else:
                    if not rc.bit(P,G1+state): d=reps[1]
                    else:
                        if not rc.bit(P,G2+state): d=reps[2]
                        else: d=reps[3]; reps[3]=reps[2]
                        reps[2]=reps[1]
                    reps[1]=reps[0]; reps[0]=d
                ln=lendec(ps,RC_); state=8 if state<7 else 11; kind="rep"
            else:
                reps[3]=reps[2];reps[2]=reps[1];reps[1]=reps[0]
                ln=lendec(ps,LC); state=7 if state<7 else 10
                lps=min(ln,3)
                sl=tree(rc,P,SLOT+lps*64,6)
                if sl<4: reps[0]=sl
                else:
                    nd=(sl>>1)-1
                    reps[0]=(2|(sl&1))<<nd
                    if sl<14: reps[0]+=rtree(rc,P,SPEC+reps[0]-sl-1,nd)
                    else:
                        reps[0]+=rc.direct(nd-4)<<4
                        reps[0]+=rtree(rc,P,AL,4)
                kind="match"
            ln+=2
            if trace: print(sym,kind,"len",ln,"dist",reps[0]+1,"pos",len(out))
            for _ in range(ln): out.append(out[-reps[0]-1])
        sym+=1
    return bytes(out)

def enc(data):
    f=[{"id":lzma.FILTER_LZMA1,"dict_size":1<<16,"lc":3,"lp":0,"pb":2}]
    c=lzma.LZMACompressor(format=lzma.FORMAT_RAW,filters=f)
    return c.compress(data)+c.flush()

tests=[b"\x00",b"\x00\x00",b"\x00"*5,b"ab",b"abcabc",b"aaaa",b"hello hello hello"]
for t in tests:
    e=enc(t)
    try:
        d=decode(e,len(t))
        print(repr(t[:12]),"->","OK" if d==t else "MISMATCH "+repr(d[:12]))
    except Exception as ex:
        print(repr(t[:12]),"-> ERROR",ex)
print("---- trace of b'aaaa' ----")
decode(enc(b"aaaa"),4,trace=True)
